from decimal import Decimal
from taf.rfrl.procedures.resources.python.utilities import convert_to_hex_pairs, append_to_file
from taf.rfrl.procedures.resources.python.log_verifiers.exceptions import InvalidEcpriDelayMeasurementSession, EcpriDelayThresholdExceeded, \
    InvalidEcpriDelayMeasurementIdOrder, InvalidEcpriDelayTimeStamp, InvalidEcpriMsg5Format, InvalidEcpriDelayMeasurementActionType

from taf.rfrl.procedures.resources.python.logger import (
    log_result,
)


def verify_ecpri_one_way_delay_measurement_procedure(sessions, logs_path):
    """
    Function verifies if all eCPRI one-way delay measurement sessions between the DU and RMOD contains the appropriate set of packets:
    * in the PCAP, one session is represented by packets with the same 'Measurement ID', additional sessions can have the same 'Measurement ID'
    due to incrementation limits.
    Measurement session should contain the following packets:
      for DL:
        - at least one packet with Action Type: Request (0x00) (from BTS to RMOD)
        - one packet with Action Type: Response (0x02) (from RMOD to BTS)
      for UL:
        - one packet with Action Type: Request with Follow_Up (0x01) (from RMOD to BTS)
        - at least one packet with Action Type: Remote Request with Follow_up (0x04) (from BTS to RMOD)
        - one packet with Action Type: Follow_up (0x05) (from RMOD to BTS)

    :param sessions: Result from group_ecpri_delay_measurement_sessions function.
                     path to function taf/rfrl/procedures/resources/python/parser/pcap_parser.py
    :type sessions: dict  {1: [pyshark.Packet, pyshark.Packet], 2: [pyshark.Packet, pyshark.Packet]}
    :param logs_path: Path to the directory where the report with invalid sessions will be saved,
                      e.g. '/home/ute/Desktop/CRT_Test/TEST_2025-01-27/17:11:49_[1][1.0]_General_SiSo_Auto_Test'
    :type logs_path: str
    :raises InvalidEcpriDelayMeasurementSession: If the eCPRI one-way delay measurement session is invalid.
    """
    report_path = f"{logs_path}/report_verify_ecpri_procedure.txt"
    invalid_sessions = 0
    for packets in sessions.values():
        invalid_packet_count = _verify_ecpri_delay_measurement_session(packets)
        if invalid_packet_count:
            invalid_sessions += 1
            packets_with_timestamps = [f"{packet.frame_info.time}: {packet.ecpri.actiontype}" for packet in packets]
            measurement_id = packets[0].ecpri.measurementid
            error_msg = f"{invalid_sessions}: Invalid count of packets for the action type: {','.join(invalid_packet_count)}\n" \
                        f"All packets from session with Measurement ID {measurement_id}: {packets_with_timestamps}\n"
            append_to_file(report_path, error_msg)

    if invalid_sessions > 0:
        raise InvalidEcpriDelayMeasurementSession(
            f"Invalid eCPRI one-way delay measurement session(s) found. For more details, refer to the path to the detailed report: {report_path}")


def verify_ecpri_one_way_delay_measurements_per_second(sessions, expected=1000):
    """
    Verifies if the number of eCPRI one-way delay measurements (feature CB009301) created during 1 second is >= the expected number.
    Function retrieves the 'Arrival Time' and 'Epoch Arrival Time' from the first packet in the first session (start point) and the last packet from
    the session indicated by the argument expected (end point), then calculates the difference between them base on 'Epoch Arrival Time'.

    :param sessions: Result from group_ecpri_delay_measurement_sessions function.
                     path to function taf/rfrl/procedures/resources/python/parser/pcap_parser.py
    :type sessions: dict  {1: [pyshark.Packet, pyshark.Packet], 2: [pyshark.Packet, pyshark.Packet]}
    :param expected: Expected number of eCPRI one-way delay measurements created during 1 second. Default value is 1000.
    :type expected: int
    :raises InvalidEcpriDelayMeasurementSession: If the count of eCPRI one-way delay measurement sessions is lower than expected.
    :raises EcpriDelayThresholdExceeded: If the eCPRI one-way delay measurement procedure exceeded the 1-second threshold.
    """
    if len(sessions) < expected:
        raise InvalidEcpriDelayMeasurementSession(f"Invalid count of eCPRI one-way delay measurement sessions\n"
                                                  f"expected: {expected}, found: {len(sessions)}")

    first_session_packet = sessions[1][0]
    last_session_packet = sessions[expected][-1]

    start_point = (Decimal(first_session_packet.frame_info.time_epoch), first_session_packet.frame_info.time)
    end_point = (Decimal(last_session_packet.frame_info.time_epoch), last_session_packet.frame_info.time)

    if end_point[0] - start_point[0] > 1:
        raise EcpriDelayThresholdExceeded(f"Expected {expected} eCPRI one-way delay measurement sessions exceeded 1 second threshold\n"
                                          f"start point: Arrival Time: {start_point[1]}, Epoch Arrival Time: {start_point[0]} UTC\n"
                                          f"end point: Arrival Time: {end_point[1]}, Epoch Arrival Time: {end_point[0]} UTC\n"
                                          f"difference: {end_point[0] - start_point[0]}.")

    log_result(f"eCPRI one-way delay measurement procedure took {format(end_point[0] - start_point[0], '.10f')} s.")


def verify_ecpri_one_way_delay_measurement_incrementation_order(sessions):
    """
    Verifies whether the 'Measurement ID' field in eCPRI one-way delay measurement sessions increments correctly during the first 1000 sessions.
    The 'Measurement ID' field should be incremented by 1 for each new measurement session. If the 'Measurement ID' reaches 0xFF (255),
    the next 'Measurement ID' should revert to 0x00 (0). First measurement session should starts with 'Measurement ID' equal to 0x00 or 0x01.

    :param sessions: Result from group_ecpri_delay_measurement_sessions function.
                     path to function taf/rfrl/procedures/resources/python/parser/pcap_parser.py
    :type sessions: dict  {1: [pyshark.Packet, pyshark.Packet], 2: [pyshark.Packet, pyshark.Packet]}
    :raises InvalidEcpriDelayMeasurementSession: If the first eCPRI one-way delay measurement session Measurement ID isn't 0x01 or 0x00.
    :raises InvalidEcpriDelayMeasurementIdOrder: If the 'Measurement ID' field in eCPRI one-way delay measurement sessions increments incorrectly.
    """
    last_measurement_id = None
    for session_number, packets in sessions.items():
        if session_number > 1000:
            break
        first_session_packet = packets[0]
        current_measurement_id = first_session_packet.ecpri.measurementid
        if session_number == 1 and current_measurement_id not in ['0x00', '0x01']:
            raise InvalidEcpriDelayMeasurementSession(f"First eCPRI delay measurement session should have Measurement ID equal to 0x01 or 0x00"
                                                      f" found: {current_measurement_id}")

        if last_measurement_id:
            expected_id = f"0x{((int(last_measurement_id, 16) + 1) % 256):02x}"
            if current_measurement_id != expected_id:
                raise InvalidEcpriDelayMeasurementIdOrder(
                    f"Measurement ID should be incremented by 1 for each new session. Last: {last_measurement_id}, expected: {expected_id}, "
                    f"found: {current_measurement_id}\nArrival Time of invalid session packet: {packets[0].frame_info.time}")

        last_measurement_id = current_measurement_id

    log_result("Measurement ID field in eCPRI one-way delay measurement sessions increments correctly.")


def verify_ecpri_delay_measurement_packet_time_stamp(sessions, logs_path):
    """
    Verifies whether eCPRI one-way delay measurement packets with Action Types: Response (0x02) and Follow_up (0x05) values that are not zero
    and are greater than the previous one.

    :param sessions: Result from group_ecpri_delay_measurement_sessions function.
                     path to function taf/rfrl/procedures/resources/python/parser/pcap_parser.py
    :type sessions: dict  {1: [pyshark.Packet, pyshark.Packet], 2: [pyshark.Packet, pyshark.Packet]}
    :param logs_path: Path to the directory where the report with invalid packets will be saved,
                      e.g. '/home/ute/Desktop/CRT_Test/TEST_2025-01-27/17:11:49_[1][1.0]_General_SiSo_Auto_Test'
    :type logs_path: str
    :raises InvalidEcpriDelayTimeStamp: If found eCPRI one-way delay measurement packets with invalid Time Stamp.
    """
    report_path = f"{logs_path}/report_verify_ecpri_time_stamp.txt"
    last_timestamp = (-1, -1)
    invalid_packets = 0

    for packets in sessions.values():
        for packet in packets:
            if packet.ecpri.actiontype in ['0x02', '0x05']:
                current_timestamp = (int(packet.ecpri.sec), int(packet.ecpri.nanosec))
                if current_timestamp < last_timestamp:
                    invalid_packets += 1
                    action_type = packet.ecpri.actiontype
                    current_t = f'{current_timestamp[0]}.{current_timestamp[1]}'
                    last_t = f'{last_timestamp[0]}.{last_timestamp[1]}'
                    error_msg = f"Invalid packet, action type: {action_type}, Time Stamp: {current_t}, " \
                                f"last Time Stamp: {last_t}, Packet Arrival Time: {packet.frame_info.time}\n"
                    append_to_file(report_path, error_msg)

                last_timestamp = current_timestamp

    if invalid_packets > 0:
        raise InvalidEcpriDelayTimeStamp(
            f"Found {invalid_packets} packets with invalid Time Stamp. For more details, refer to the path to the detailed report: {report_path}")


def verify_ecpri_message_type_5_fields(pcap_capture, logs_path):
    """
    Verifies whether the eCPRI one-way delay measurement msg type 5 packets have correct format.

    :param pcap_capture: Filtered PCAP with raw data included (used Wireshark display filter 'ecpri.type == 0x05').
                         Used function: filter_pcap(pcap_path, display_filter='ecpri.type == 0x05', use_ek=True, include_raw=True)
                         from taf.rfrl.procedures.resources.python.parser.pcap_parser
    :type pcap_capture: pyshark.FileCapture object
    :param logs_path: Path to the logs directory where the report with invalid packets will be saved,
                      e.g. '/home/ute/Desktop/CRT_Test/TEST_2025-01-27/17:11:49_[1][1.0]_General_SiSo_Auto_Test'
    :type logs_path: str
    :raises InvalidEcpriMsg5Format: If found eCPRI one-way delay measurement msg type 5 packet(s) with invalid format.
    """
    report_path = f"{logs_path}/report_verify_ecpri_msg5.txt"
    invalid_packets = 0
    for packet in pcap_capture:
        errors = _check_packet_format(packet)
        if errors:
            invalid_packets += 1
            errors = '\n'.join([f"Packet Arrival Time: {packet.frame_info.time.value}\n"
                                f"eCPRI layer raw data: {convert_to_hex_pairs(getattr(packet.ecpri_raw, '_fields_dict'))}"] + errors) + '\n\n'
            append_to_file(report_path, errors)

    if invalid_packets > 0:
        raise InvalidEcpriMsg5Format(f"Found {invalid_packets} eCPRI one-way delay msg type 5 packet(s) with invalid format. "
                                     f"For more details, refer to the path to the detailed report: {report_path}")


def _verify_ecpri_delay_measurement_session(session_packets):
    """
    Verifies if eCPRI one-way delay measurement session have the appropriate set of packets.
    Measurement session should contain the following packets:
        for DL:
            - at least one packet with Action Type: Request (0x00) (from BTS to RMOD)
            - one packet with Action Type: Response (0x02) (from RMOD to BTS)
        for UL:
            - one packet with Action Type: Request with Follow_Up (0x01) (from RMOD to BTS)
            - at least one packet with Action Type: Remote Request with Follow_up (0x04) (from BTS to RMOD)
            - one packet with Action Type: Follow_up (0x05) (from RMOD to BTS)

    :param session_packets: List of packets representing one eCPRI delay measurement session.
    :type session_packets: list[pyshark.Packet objects]
    :return: Empty list if the session is valid, otherwise a list with all missing action types with counts
    :rtype: list[str]
    :raises InvalidEcpriDelayMeasurementActionType: If the eCPRI one-way delay measurement action type is invalid.
    """

    mandatory_action_types = {
        '0x00': {'condition': lambda count: count >= 1, 'info': '>= 1'},
        '0x01': {'condition': lambda count: count == 1, 'info': '== 1'},
        '0x02': {'condition': lambda count: count == 1, 'info': '== 1'},
        '0x04': {'condition': lambda count: count >= 1, 'info': '>= 1'},
        '0x05': {'condition': lambda count: count == 1, 'info': '== 1'},
    }
    action_counts = {'0x00': 0, '0x01': 0, '0x02': 0, '0x04': 0, '0x05': 0}

    for packet in session_packets:
        if packet.ecpri.actiontype not in mandatory_action_types:
            raise InvalidEcpriDelayMeasurementActionType(
                f"Invalid packet action type: {packet.ecpri.actiontype}, allowed: {list(mandatory_action_types.keys())}. "
                f"Packet Arrival Time: {packet.frame_info.time}")
        action_counts[packet.ecpri.actiontype] += 1

    errors = []
    for action, data in mandatory_action_types.items():
        if not data['condition'](action_counts[action]):
            errors.append(f'[{action} number of occurrences: {action_counts[action]} should be {data["info"]}]')

    return errors


def _check_packet_format(packet):
    """
    Verifies whether the eCPRI one-way delay measurement msg type 5 packet has correct format.
    Required:
        - Frame should have max 64 bytes
        - eCPRI frame layer should have at least 24 bytes
        - eCPRI frame Header (4 bytes) should be equal '1005' + payload_size (2 bytes) and should be placed in the 1st to 4th octet
          octet 1 (1 byte) = Protocol Revision, Reserved, C-Bit expected: '10'
          octet 2 (1 byte) = Message Type expected: '05'
          octet 3 (2 bytes) = Payload Size, expected value not checked
        - [eCPRI layer] Measurement ID (1 byte) should be placed in the 5th octet
        - [eCPRI layer] Action Type (1 byte) should be placed in the 6th octet
        - [eCPRI layer] TimeStamp sec (6 bytes) should start at the 7th octet and end at the 12th octet
        - [eCPRI layer] TimeStamp nanosec (4 bytes) should start at the 13th octet and end at the 16th octet
        - [eCPRI layer] Compensation value (8 bytes) should start at the 17th octet and end at the 24th octet

    :param packet: eCPRI one-way delay measurement msg type 5 packet.
    :type packet: pyshark.Packet object with raw data included
    :return: List with all errors found in the packet.
    :rtype: list[str]
    """
    frame_raw_data = convert_to_hex_pairs(getattr(packet.frame_raw, '_fields_dict'))
    ecpri_raw_data = convert_to_hex_pairs(getattr(packet.ecpri_raw, '_fields_dict'))

    errors = []
    if len(frame_raw_data) > 64:
        errors.append(f"-- Frame should have max 64 Bytes, found {len(frame_raw_data)} Bytes")
    if len(ecpri_raw_data) < 24:
        errors.append(f"-- eCPRI layer should have at least 24 Bytes, found {len(ecpri_raw_data)} Bytes")

    packet_header_expected_raw = '1005' + format(len(packet.ecpri.payload.value), '04x')
    checks = [
        (''.join(ecpri_raw_data[:4]), packet_header_expected_raw, "Header (octets 1-4)"),
        (packet.ecpri.measurementid.raw, ecpri_raw_data[4], "Measurement ID (octet 5)"),
        (packet.ecpri.actiontype.raw, ecpri_raw_data[5], "Action Type (octet 6)"),
        (packet.ecpri.sec.raw, ''.join(ecpri_raw_data[6:12]), "Time Stamp sec (octets 7-12)"),
        (packet.ecpri.nanosec.raw, ''.join(ecpri_raw_data[12:16]), "Time Stamp nanosec (octets 13-16)"),
        (packet.ecpri.compval.raw, ''.join(ecpri_raw_data[16:24]), "Compensation value (octets 17-24)"),
    ]

    for actual, expected, description in checks:
        if actual != expected:
            errors.append(f"-- [eCPRI layer] Invalid {description} format. Based on octets from eCPRI raw data, "
                          f"expected: {expected}, found: {actual} (extracted from a specific eCPRI field)")
    return errors
